-- Copiado sem alterações da migração original: migration_20260929_164547000
begin;
create function public.amcf_test_assert(ok boolean, label text) returns void language plpgsql as $$ begin if ok is not true then raise exception 'TEST FAILED: %',label; end if; end $$;
insert into public.amcf_members(id,name,email,role,status) values ('10000000-0000-4000-8000-000000000001','Administrador sintético','admin@amcf-test.invalid','admin','active'),('10000000-0000-4000-8000-000000000002','Assistente sintético A','a@amcf-test.invalid','assistant','active'),('10000000-0000-4000-8000-000000000003','Assistente sintético B','b@amcf-test.invalid','assistant','active');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","aal":"aal2","role":"authenticated"}',true);
insert into public.amcf_contacts(id,name,responsible_id,created_by) values ('20000000-0000-4000-8000-000000000001','Contato sintético A','10000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001'),('20000000-0000-4000-8000-000000000002','Contato sintético B','10000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000001');
insert into public.amcf_cases(id,reference,title,contact_id,service,stage_id,responsible_id,created_by) select '30000000-0000-4000-8000-000000000001','TEST-RLS-A','Caso sintético A','20000000-0000-4000-8000-000000000001','Teste administrativo',id,'10000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001' from public.amcf_case_stages where position=1;
insert into public.amcf_cases(id,reference,title,contact_id,service,stage_id,responsible_id,created_by) select '30000000-0000-4000-8000-000000000002','TEST-RLS-B','Caso sintético B','20000000-0000-4000-8000-000000000002','Teste administrativo',id,'10000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001' from public.amcf_case_stages where position=1;
insert into public.amcf_case_assignments(case_id,member_id) values ('30000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000002'),('30000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000003');
set local role authenticated;
select public.amcf_test_assert((select count(*)=2 from public.amcf_cases),'admin reads both cases');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","aal":"aal2","role":"authenticated"}',true);
select public.amcf_test_assert((select count(*)=1 from public.amcf_cases),'assistant reads only assigned case');
select public.amcf_test_assert((select count(*)=0 from public.amcf_cases where id='30000000-0000-4000-8000-000000000002'),'known foreign case ID hidden');
select public.amcf_test_assert((select count(*)=1 from public.amcf_contacts),'contact isolation');
with updated as (update public.amcf_cases set title='Forbidden' where id='30000000-0000-4000-8000-000000000002' returning id) select public.amcf_test_assert((select count(*)=0 from updated),'foreign update denied');
with updated as (update public.amcf_members set role='admin' where id='10000000-0000-4000-8000-000000000002' returning id) select public.amcf_test_assert((select count(*)=0 from updated),'self promotion denied');
insert into public.amcf_tasks(title,case_id,due_on) values('Tarefa sintética atribuída','30000000-0000-4000-8000-000000000001',current_date);
select public.amcf_test_assert((select count(*)=1 from public.amcf_tasks),'assigned task inserted');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","aal":"aal1","role":"authenticated"}',true);
select public.amcf_test_assert((select count(*)=0 from public.amcf_cases),'MFA required in database');
reset role;
update public.amcf_members set status='revoked' where id='10000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","aal":"aal2","role":"authenticated"}',true);
select public.amcf_test_assert((select count(*)=0 from public.amcf_cases),'revoked member cannot reuse session');
reset role;
rollback;